INSERT INTO pages (slug, title, content, type, status) VALUES 
('about', 'About Us', '<p style="line-height: 1.8; margin-bottom: 1rem;">Welcome to Kothbel! We are dedicated to providing the best products with the highest quality and affordable prices.</p><p style="line-height: 1.8;">Our mission is to bring joy to our customers through excellent service and unique items.</p>', 'page', 'published'),

('privacy', 'Privacy Policy', '<p style="line-height: 1.8;">This privacy policy sets out how we use and protect any information that you give us when you use this website.</p><h3 style="margin-top: 1.5rem;">What we collect</h3><p style="line-height: 1.8;">We may collect your name, contact information including email address, and demographic information such as postcode, preferences, and interests.</p>', 'page', 'published'),

('terms', 'Terms & Conditions', '<p style="line-height: 1.8;">Welcome to our website. If you continue to browse and use this website, you are agreeing to comply with and be bound by the following terms and conditions of use.</p><h3 style="margin-top: 1.5rem;">Use of the Website</h3><p style="line-height: 1.8;">The content of the pages of this website is for your general information and use only. It is subject to change without notice.</p>', 'page', 'published'),

('refund', 'Return & Refund Policy', '<p style="line-height: 1.8;">If you are not entirely satisfied with your purchase, we''re here to help.</p><h3 style="margin-top: 1.5rem;">Returns</h3><p style="line-height: 1.8;">You have 7 calendar days to return an item from the date you received it. To be eligible for a return, your item must be unused and in the same condition that you received it.</p><h3 style="margin-top: 1.5rem;">Refunds</h3><p style="line-height: 1.8;">Once we receive your item, we will inspect it and notify you that we have received your returned item. If your return is approved, we will initiate a refund to your original method of payment.</p>', 'page', 'published'),

('contact', 'Contact Us', '<div style="background: var(--bg-color); padding: 2rem; border-radius: var(--radius-lg); box-shadow: var(--shadow);"><p style="margin-bottom: 1.5rem;"><i class="ph-bold ph-phone"></i> +880 1703-968638</p><p style="margin-bottom: 1.5rem;"><i class="ph-bold ph-envelope"></i> support@kothbel.com</p><p><i class="ph-bold ph-map-pin"></i> Dhaka, Bangladesh</p></div>', 'page', 'published')
ON CONFLICT(slug) DO UPDATE SET content=excluded.content, title=excluded.title;
